function NavItem([string]$icon,[string]$label,[bool]$active) {
  $bg = if($active){'var:primary'}else{'var:surface'}
  $fg = if($active){'var:white'}else{'var:text'}
  return "<Frame w=`"fill`" h={42} bg=`"$bg`" rounded={9} flex=`"row`" gap={14} items=`"center`" px={14}><Icon name=`"$icon`" size={19} color=`"$fg`"/><Text font=`"Figtree`" size={15} weight=`"semibold`" color=`"$fg`">$label</Text></Frame>"
}

