}
function Button([string]$label,[bool]$secondary=$false) { $bg=if($secondary){'var:surface'}else{'var:primary'}; $fg=if($secondary){'var:text'}else{'var:white'}; $stroke=if($secondary){' stroke="var:border-strong" strokeWidth={1}'}else{''}; return "<Frame h={54} bg=`"$bg`"$stroke rounded={10} flex=`"row`" items=`"center`" px={22}><Text font=`"Figtree`" size={16} weight=`"bold`" color=`"$fg`">$label</Text></Frame>" }
function Field([string]$label,[string]$value='',[string]$placeholder='',[bool]$select=$false,[bool]$textarea=$false) { $h=if($textarea){140}else{56}; $inner=if($value -ne ''){$value}else{$placeholder}; $color=if($value -ne ''){'var:text'}else{'var:text-subtle'}; $tail=if($select){'<Icon name="lucide:chevron-down" size={20} color="var:text-muted"/>'}else{''}; return "<Frame flex=`"col`" gap={9}><Text font=`"Figtree`" size={16} weight=`"bold`" color=`"var:text`">$label</Text><Frame w=`"fill`" h={$h} bg=`"var:surface`" stroke=`"var:border-strong`" strokeWidth={1} rounded={10} flex=`"row`" items=`"$([string]::new('center'))`" justify=`"between`" p={16}><Text font=`"Figtree`" size={16} color=`"$color`">$inner</Text>$tail</Frame></Frame>" }

