  'Leases / Create' = (Header 'LEASES' 'Create lease' 'Assign a tenant to an available apartment and set the rental terms.' '<Frame h={36} bg="var:emerald-50" rounded={20} flex="row" items="center" px={16}><Text font="Figtree" size={15} weight="bold" color="var:emerald-700">New lease · Active</Text></Frame>') + '<Frame w="fill" bg="var:surface" stroke="var:border" strokeWidth={1} rounded={14} flex="col" gap={28} p={40}><Text font="Figtree" size={24} weight="bold" color="var:text-strong">Rental assignment</Text><Frame flex="row" gap={30}><Frame w="fill">' + (Field 'Tenant *' '' 'Select tenant' $true) + '</Frame><Frame w="fill">' + (Field 'Apartment *' '' 'Select available apartment' $true) + '</Frame></Frame><Frame flex="row" gap={30}><Frame w="fill">' + (Field 'Start date *' '' 'dd/mm/yyyy') + '</Frame><Frame w="fill">' + (Field 'End date' '' 'dd/mm/yyyy') + '</Frame></Frame><Text font="Figtree" size={24} weight="bold" color="var:text-strong">Financial information</Text><Frame flex="row" gap={30}><Frame w="fill">' + (Field 'Monthly rent *' '' 'PHP ') + '</Frame><Frame w="fill">' + (Field 'Security deposit' '' 'PHP ') + '</Frame></Frame>' + (Field 'Lease terms' '' 'Enter additional lease terms or notes...' $false $true) + '<Frame flex="row" justify="end" gap={14}>' + (Button 'Cancel' $true) + (Button 'Create active lease') + '</Frame></Frame>';
  'Payments / Create' = (Header 'PAYMENTS' 'Record payment' 'Apply a tenant payment to an outstanding bill.' '<Text font="Figtree" size="16" weight="bold" color="var:text-muted">← Back to bills</Text>') + '<Frame flex="row" gap={30}><Frame w="fill" bg="var:surface" stroke="var:border" strokeWidth={1} rounded={14} flex="col" gap={24} p={40}><Text font="Figtree" size={24} weight="bold" color="var:text-strong">Payment information</Text>' + (Field 'Bill / tenant *' '' 'Select an outstanding bill' $true) + '<Frame flex="row" gap={30}><Frame w="fill">' + (Field 'Payment date *' '19/09/2026') + '</Frame><Frame w="fill">' + (Field 'Amount paid *' '' 'PHP ') + '</Frame></Frame><Frame flex="row" gap={30}><Frame w="fill">' + (Field 'Payment method *' 'Cash' '' $true) + '</Frame><Frame w="fill">' + (Field 'Reference number' '' 'e.g. GC-...1842') + '</Frame></Frame>' + (Field 'Notes' '' 'Optional notes...' $false $true) + '<Frame flex="row" justify="end" gap={14}>' + (Button 'Cancel' $true) + (Button 'Record payment') + '</Frame></Frame><Frame w={400} bg="var:surface" stroke="var:border" strokeWidth={1} rounded={14} flex="col" gap={20} p={30}><Text font="Figtree" size={14} weight="bold" color="var:text-muted">SELECTED BILL</Text><Text font="Figtree" size={22} weight="bold" color="var:text-strong">Bill summary</Text><Text font="Figtree" size={16} color="var:text-muted">Tenant                                      —</Text><Text font="Figtree" size={16} color="var:text-muted">Apartment                                  —</Text><Text font="Figtree" size={16} color="var:text-muted">Bill total                                  —</Text><Text font="Figtree" size={16} color="var:text-muted">Previously paid                         —</Text><Frame h={64} bg="var:slate-50" rounded={10} flex="row" items="center" px={18}><Text font="Figtree" size={16} color="var:text-muted">Remaining balance                    —</Text></Frame></Frame></Frame>'
}

$routes = @(
  @{n='NEW FLOW / Admin HD / Dashboard'; e='ADMIN PORTAL'; t='Welcome back, Admin'; d='Here is what is happening across your properties today.'; b=$dashboard; a='dashboard'},
  @{n='NEW FLOW / Admin HD / Apartments / Index'; e='PROPERTY MANAGEMENT'; t='Apartments'; d='Manage inventory, rates, and availability across all units.'; b=$apartments; a='apartments'},
  @{n='NEW FLOW / Admin HD / Apartments / Create'; e='PROPERTY MANAGEMENT'; t='Add apartment'; d='Create a unit record with rates, capacity, and availability.'; b=$formBodies['Apartments / Create']; a='apartments'},
  @{n='NEW FLOW / Admin HD / Tenants / Index'; e='PEOPLE'; t='Tenants'; d='Keep resident contact details, status, and lease context organized.'; b=$tenants; a='tenants'},
  @{n='NEW FLOW / Admin HD / Leases / Index'; e='LEASES'; t='Leases'; d='Monitor tenant rental agreements and apartment assignments.'; b=$leases; a='leases'},
  @{n='NEW FLOW / Admin HD / Leases / Create'; e='LEASES'; t='Create lease'; d='Assign a tenant to an available apartment and set the rental terms.'; b=$formBodies['Leases / Create']; a='leases'},
  @{n='NEW FLOW / Admin HD / Maintenance / Index'; e='MAINTENANCE'; t='Maintenance requests'; d='Track repair and upkeep requests across the building.'; b=$maintenance; a='maintenance'},
  @{n='NEW FLOW / Admin HD / Maintenance / Create'; e='MAINTENANCE'; t='Submit a request'; d='Tell us what needs attention and we will get on it.'; b=$maintenanceCreate; a='maintenance'},
  @{n='NEW FLOW / Admin HD / Bills / Index'; e='FINANCE'; t='Bills'; d='Monitor rent charges, balances, and due dates across active leases.'; b=$bills; a='bills'},
  @{n='NEW FLOW / Admin HD / Payments / Index'; e='FINANCE'; t='Payment history'; d='Review and reconcile all recorded tenant payments.'; b=$payments; a='payments'},
  @{n='NEW FLOW / Admin HD / Payments / Create'; e='PAYMENTS'; t='Record payment'; d='Apply a tenant payment to an outstanding bill.'; b=$formBodies['Payments / Create']; a='payments'},
  @{n='NEW FLOW / Admin HD / Profile'; e='ACCOUNT'; t='Profile settings'; d='Manage your personal information, password, and account access.'; b=$profile; a='profile'}
)

foreach($r in $routes){
  $jsx = Shell $r.n $r.e $r.t $r.d $r.b $r.a
  $arg = $jsx -replace '"','`"'
  node src/index.js render $arg --collection 'StayTrack Source'
}
